package com.campusiq.platform.entity; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="platform_stat_snapshots") public class PlatformStatSnapshot { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) @JoinColumn(name="account_id",unique=true) private UserPlatformAccount account; private Long rating,globalRank,countryRank; private Integer problemsSolved,easySolved,mediumSolved,hardSolved; private Double contestRating,currentRating,maxRating; private Long contestRanking,codingScore; private Double contestTopPercent; private Integer currentStreak,maxStreak; private String stars; @Column(columnDefinition="TEXT") private String rawData; @Column(nullable=false) private Instant capturedAt; public void setAccount(UserPlatformAccount v){account=v;} public void updateFrom(Long rank,Integer total,Integer easy,Integer medium,Integer hard,Double rating,Long contestRank,Double top,Double current,Double maximum,Long score,Integer streak,Integer maxStreakValue,Long country,String starValue,String raw){globalRank=rank;problemsSolved=total;easySolved=easy;mediumSolved=medium;hardSolved=hard;contestRating=rating;contestRanking=contestRank;contestTopPercent=top;currentRating=current;maxRating=maximum;codingScore=score;currentStreak=streak;maxStreak=maxStreakValue;countryRank=country;stars=starValue;rawData=raw;capturedAt=Instant.now();} public Long getGlobalRank(){return globalRank;} public Long getCountryRank(){return countryRank;} public String getStars(){return stars;} public Integer getProblemsSolved(){return problemsSolved;} public Integer getEasySolved(){return easySolved;} public Integer getMediumSolved(){return mediumSolved;} public Integer getHardSolved(){return hardSolved;} public Double getContestRating(){return contestRating;} public Long getContestRanking(){return contestRanking;} public Double getContestTopPercent(){return contestTopPercent;} public Double getCurrentRating(){return currentRating;} public Double getMaxRating(){return maxRating;} public Long getCodingScore(){return codingScore;} public Integer getCurrentStreak(){return currentStreak;} public Integer getMaxStreak(){return maxStreak;} public Instant getCapturedAt(){return capturedAt;} }
